// PV7: the SigV4 S3 client. Signatures are checked against AWS's own published example; the wire calls run against
// s3rver, an S3-compatible server in this test process (path-style, its fixed test credentials). Generated bytes only.
// The end-to-end run against a real bucket waits for BYO_TEST_BUCKET_* (WAITING W-7).

import { createHash, randomBytes } from "node:crypto";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { normalizeUserAgent, objectUrl, presign, s3Client, signHeaders, uriEncode, type S3Config } from "@saas/shared/s3";

describe("SigV4 signing", () => {
  // AWS documentation, "Signature Calculations for the Authorization Header", example: GET Object.
  const aws: S3Config = { endpoint: "https://s3.amazonaws.com", region: "us-east-1", bucket: "examplebucket", accessKeyId: "AKIAIOSFODNN7EXAMPLE", secretAccessKey: "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY" };

  it("matches AWS's published signature for GET Object", async () => {
    const url = objectUrl(aws, "test.txt");
    expect(url.toString()).toBe("https://examplebucket.s3.amazonaws.com/test.txt");
    const h = await signHeaders(aws, "GET", url, { range: "bytes=0-9" }, "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", new Date("2013-05-24T00:00:00Z"));
    expect(h.authorization).toBe(
      "AWS4-HMAC-SHA256 Credential=AKIAIOSFODNN7EXAMPLE/20130524/us-east-1/s3/aws4_request, SignedHeaders=host;range;x-amz-content-sha256;x-amz-date, Signature=f0e8bdb87c964420e857bd35b5d6ed310bd44f0170aba48dd91039c6036bdb41",
    );
  });

  it("matches AWS's published presigned URL", async () => {
    const url = await presign(aws, "GET", "test.txt", 86400, new Date("2013-05-24T00:00:00Z"));
    expect(new URL(url).searchParams.get("X-Amz-Signature")).toBe("aeeed9bbccd4d02ee5c0109b86d86835f995330da4c265957d157751f604d404");
  });

  it("encodes keys and checks the User-Agent", () => {
    expect(uriEncode("a b/ç+?.png", true)).toBe("a%20b/%C3%A7%2B%3F.png");
    expect(objectUrl({ ...aws, pathStyle: true, endpoint: "http://127.0.0.1:9000" }, "x/y.png").toString()).toBe("http://127.0.0.1:9000/examplebucket/x/y.png");
    expect(normalizeUserAgent(" pixvault ")).toBe("pixvault");
    expect(() => normalizeUserAgent("badé")).toThrow();
  });
});

describe("the S3 client against an S3-compatible server", () => {
  let server: { run(): Promise<{ port: number }>; close(): Promise<void> };
  let dir: string;
  let cfg: S3Config;

  beforeAll(async () => {
    dir = mkdtempSync(join(tmpdir(), "pv-s3-"));
    const S3rver = (await import("s3rver")).default as unknown as new (o: Record<string, unknown>) => typeof server;
    server = new S3rver({ port: 0, address: "127.0.0.1", silent: true, directory: dir, configureBuckets: [{ name: "byo-test" }] });
    const { port } = await server.run();
    // s3rver's fixed test credentials.
    cfg = { endpoint: `http://127.0.0.1:${port}`, region: "us-east-1", bucket: "byo-test", accessKeyId: "S3RVER", secretAccessKey: "S3RVER", pathStyle: true };
  });
  afterAll(async () => {
    await server?.close();
    rmSync(dir, { recursive: true, force: true });
  });

  it("puts, heads, gets (with a range), lists and deletes an object", async () => {
    const c = s3Client(cfg);
    const bytes = randomBytes(5000);
    await c.put("org/o/lib/l/blob/a", bytes, { contentType: "application/octet-stream", sha256: createHash("sha256").update(bytes).digest("hex") });
    expect(await c.head("org/o/lib/l/blob/a")).toMatchObject({ size: 5000 });
    const got = await c.get("org/o/lib/l/blob/a");
    expect(Buffer.from(await got!.arrayBuffer()).equals(bytes)).toBe(true);
    const part = await c.get("org/o/lib/l/blob/a", "bytes=10-19");
    expect(Buffer.from(await part!.arrayBuffer()).equals(bytes.subarray(10, 20))).toBe(true);
    expect((await c.list("org/o/lib/l/")).map((o) => o.key)).toEqual(["org/o/lib/l/blob/a"]);
    await c.delete("org/o/lib/l/blob/a");
    expect(await c.head("org/o/lib/l/blob/a")).toBeNull();
    expect(await c.get("org/o/lib/l/blob/a")).toBeNull();
  });

  it("assembles a multipart upload in part order", async () => {
    const c = s3Client(cfg);
    const p1 = randomBytes(5 * 1024 * 1024);
    const p2 = randomBytes(1234);
    const id = await c.createMultipart("org/o/lib/l/blob/big");
    const r2 = await c.uploadPart("org/o/lib/l/blob/big", id, 2, p2);
    const r1 = await c.uploadPart("org/o/lib/l/blob/big", id, 1, p1);
    await c.completeMultipart("org/o/lib/l/blob/big", id, [r2, r1]);
    const got = Buffer.from(await (await c.get("org/o/lib/l/blob/big"))!.arrayBuffer());
    expect(got.equals(Buffer.concat([p1, p2]))).toBe(true);
  });

  it("an unknown access key and a missing bucket are clear errors, never leaking the URL", async () => {
    // (s3rver doesn't check secrets; signing itself is pinned by AWS's examples above)
    const bad = s3Client({ ...cfg, accessKeyId: "NOT-A-KEY" });
    await expect(bad.put("k", randomBytes(10))).rejects.toMatchObject({ status: 403 });
    const none = s3Client({ ...cfg, bucket: "no-such-bucket" });
    const e = await none.put("k", randomBytes(10)).catch((x: Error) => x);
    expect(String(e)).toMatch(/^Error: S3 404 NoSuchBucket$/);
    expect(String(e)).not.toContain("127.0.0.1");
    // a read or delete on a missing bucket is an error, not "no such file" (PV-45)
    await expect(none.get("k")).rejects.toMatchObject({ code: "NoSuchBucket" });
    await expect(none.delete("k")).rejects.toMatchObject({ code: "NoSuchBucket" });
    expect(await s3Client(cfg).get("org/o/lib/l/never-written")).toBeNull();
  });
});
